{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "SRT2104, a thiazole-containing small molecule, had absolute oral bioavailability of 13.8% in a Phase 1 human study, below the 20% threshold; the high assay-transfer score supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Revefenacin had absolute oral bioavailability <3% in humans after oral administration, providing direct human evidence of low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor structurally related to the query's hydroxyethylene/peptide scaffold, had only 0.5% oral bioavailability in humans, strongly supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Remikiren, another renin inhibitor with a similar peptidomimetic backbone, had absolute bioavailability of 0.3% in healthy volunteers, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Alvimopan had human oral bioavailability of 6%, well below the 20% threshold, adding further evidence that this chemical space tends to have low oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues, including direct human absolute bioavailability measurements, show F well below 20% (0.2–13.8%). The query's peptidomimetic renin-inhibitor-like structure is closely mirrored by enalkiren and remikiren, which have F <1%. Therefore the query is predicted to have low absolute oral bioavailability.",
  "evidence_gaps": [
    "No direct fed-state bioavailability experiment for the query or exact query PK data; food effects could modulate absorption but are unlikely to raise F from <1–14% to >=20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

